const CACHE='fridgeful-3ade8f484427';const ASSETS=["/","/index.html","/manifest.webmanifest","/icon.svg","/brand.svg","/icon-192.png","/icon-512.png","/apple-touch-icon.png","/assets/index-BvTeCQRo.js","/assets/index-SeEh_mvi.css"];
